window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d4f40b95450712d1"]={"versions": [{"id": "FIG-d4f40b95450712d1", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB (Virtual Functional Bus) Komponentendiagramm / Software-Architekturdiagramm (UML-2-Komponentennotation mit AUTOSAR-spezifischen VFB-Portsymbolen).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Veranschaulichung der Mehrfachinstanziierung (<em>Multiple Instantiation</em>) eines einzelnen Software-Komponententyps (<code>AtomicSoftwareComponentType</code> bzw. <code>ApplicationSoftwareComponentType</code>: <code>SeatHeatingControl</code>) in zwei distinkte Komponenten-Prototypen (<code>SwComponentPrototype</code>: <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>).</li>\n<li><strong>Systemkontext:</strong> VFB-Ebene vor der Allokation auf konkrete Steuergeräte (ECUs). Zeigt die vollständige logische Entkopplung von identischer Implementierung und instanzspezifischer Schnittstellenbindung für symmetrische Fahrzeugfunktionen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponententyp & Prototypen:</strong></li>\n<li><code>SeatHeatingControl</code> (<code>isOfType</code>): Basistyp, der das gemeinsame <code>SwcInternalBehavior</code> definiert.</li>\n<li><code>SHCFrontLeft</code>, <code>SHCFrontRight</code>: Konkrete Komponenten-Prototypen (<code>SwComponentPrototype</code>) mit identischem Port-Layout, aber separaten Instanzkontexten.</li>\n<li><strong>Schnittstellen & Port-Typen (pro Instanz):</strong></li>\n<li><strong>Sender-Receiver-Ports (Datenfluss):</strong></li>\n<li><code>SeatSwitch</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Einlesen des Taster-/Schalterzustands.</li>\n<li><code>PowerManagement</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Empfang von Lastabwurf- und Leistungsbegrenzungsvorgaben des Bordnetzmanagements.</li>\n<li><code>DialLED</code> (P-Port / Provider): Schwarzes Dreieck auswärts gerichtet; Ansteuerung der Statusanzeige/LEDs am Bedienelement.</li>\n<li><strong>Client-Server-Ports (Operationsbasiert):</strong></li>\n<li><code>Setting</code> (P-Port / Server): Kreis-/Ball-Symbol; Bereitstellung von Einstellungsdiensten oder Betriebsarten.</li>\n<li><code>HeatingElement</code> (R-Port / Client): Socket-/Halbkreis-Symbol einwärts gerichtet; Aufruf von Aktor-Services (z. B. Endstufen-/PWM-Regelung der Heizmatten).</li>\n<li><strong>Spezialisierte AUTOSAR-Service- & Parameter-Ports:</strong></li>\n<li><code>Calibration</code> (Parameter-Port): Weißes Dreieck einwärts gerichtet; typisiert über ein <code>ParameterInterface</code> zum Zugriff auf Kennlinien und Schwellwerte.</li>\n<li><code>nv</code> (NvData-Port): Dunkler Block mit NV-Symbol am unteren Rand; Anbindung an das <code>NvDataInterface</code> zur persistenten Speicherung (z. B. Memory-Funktion/letzte Heizstufe via NvM).</li>\n<li><code>ecuMode</code> (Mode-Switch-Port): Dunkler Block mit weißem Dreieck am unteren Rand; Typisiert über <code>ModeSwitchInterface</code> zur Steuerung des Run-Status abhängig von BSW-Modi (z. B. <code>RUN</code>, <code>POST_RUN</code>, <code>SHUTDOWN</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Strukturdiagramm handelt, wird kein Zeitablauf dargestellt. Das Laufzeitverhalten leitet sich aus den RTE-Events ab:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Init-/Startup-Phase:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Moduswechsel an <code>ecuMode</code> erzeugt ein <code>ModeSwitchEvent</code>.</li>\n<li>Restore der letzten Betriebszustände über <code>nv</code> (asynchroner NvM-Read-Job bzw. Initial-RAM-Mirror-Lesezugriff).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zyklischer Regelkreis:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>TimingEvent</code> oder <code>DataReceivedEvent</code> an <code>SeatSwitch</code> aktiviert die Steuerungs-Runnable.</li>\n<li>Prüfung der zulässigen Heizleistung gegen empfangene Drosselungswerte aus <code>PowerManagement</code>.</li>\n<li>Abgleich mit Kennwerten über den <code>Calibration</code>-Port.</li>\n<li>Synchoner/asynchroner Operationsaufruf (<code>Rte_Call</code>) an <code>HeatingElement</code> zur Bestromung der Heizdrähte.</li>\n<li>Asynchrones Datensenden (<code>Rte_Write</code>) des aktuellen Zustands an <code>DialLED</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbruch-/Grenzbedingungen:</strong> Bei Lastabwurfanforderung via <code>PowerManagement</code> oder Erkennung von Unter-/Überspannung erfolgt die Abregelung oder Abschaltung des Heizelements.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Mehrfachinstanziierung im BSW/RTE-Vertrag:</strong></li>\n<li>Im SWC-Descriptor muss zwingend <code>supportsMultipleInstantiation = true</code> gesetzt sein.</li>\n<li>Der C-Code der Komponente muss <strong>vollständig reentrant</strong> sein: Keine statischen/globalen Variablen (<code>static</code> im Funktionsscope oder Dateiscope) ohne Instanzbezug!</li>\n<li><strong>RTE-API & Instanz-Handling:</strong></li>\n<li>Die RTE generiert instanzbezogene Schnittstellen. Entweder über separate API-Präfixe pro Prototyp (z. B. <code>Rte_IRead_SHCFrontLeft_SeatSwitch_...</code> und <code>Rte_IRead_SHCFrontRight_SeatSwitch_...</code>) oder über Übergabe eines Instanzzeigers (<code>Rte_Instance self</code>) als ersten Funktionsparameter an die Runnables.</li>\n<li><strong>Speicher- und Datenhaltung (RAM/ROM/NVRAM):</strong></li>\n<li><strong>Code-Sharing:</strong> Der ausführbare Maschinencode (<code>.text</code>) liegt nur einmal im ROM vor.</li>\n<li><strong>RAM-Trennung:</strong> Instanzdaten (<code>.data</code>, <code>.bss</code>) müssen für <code>SHCFrontLeft</code> und <code>SHCFrontRight</code> getrennt allokiert werden (z. B. via RTE Application Types / Instanzstrukturen).</li>\n<li><strong>NVRAM:</strong> Der Port <code>nv</code> erfordert im BSW-Mapping zwingend separate NVRAM-Block-IDs (<code>NvMBlockDescriptor</code>) pro Instanz, um ein gegenseitiges Überschreiben der persistenten Parameter der linken und rechten Sitzheizung zu verhindern.</li>\n<li><strong>Kalibrierung:</strong> Konfiguration entscheidet, ob <code>Calibration</code> als <code>SharedAxis</code>/gemeinsamer Parametersatz oder instanzspezifisch (<code>InstantiationDataDefSet</code>) vorgehalten wird.</li>\n</ul>"}, {"id": "FIG-be9c3b3fc79318cb", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB (Virtual Functional Bus) Komponentendiagramm / Software-Architekturdiagramm (UML-2-Komponentennotation mit AUTOSAR-spezifischen VFB-Portsymbolen).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Veranschaulichung der Mehrfachinstanziierung (<em>Multiple Instantiation</em>) eines einzelnen Software-Komponententyps (<code>AtomicSoftwareComponentType</code> bzw. <code>ApplicationSoftwareComponentType</code>: <code>SeatHeatingControl</code>) in zwei distinkte Komponenten-Prototypen (<code>SwComponentPrototype</code>: <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>).</li>\n<li><strong>Systemkontext:</strong> VFB-Ebene vor der Allokation auf konkrete Steuergeräte (ECUs). Zeigt die vollständige logische Entkopplung von identischer Implementierung und instanzspezifischer Schnittstellenbindung für symmetrische Fahrzeugfunktionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponententyp & Prototypen:</strong></li>\n<li><code>SeatHeatingControl</code> (<code>isOfType</code>): Basistyp, der das gemeinsame <code>SwcInternalBehavior</code> definiert.</li>\n<li><code>SHCFrontLeft</code>, <code>SHCFrontRight</code>: Konkrete Komponenten-Prototypen (<code>SwComponentPrototype</code>) mit identischem Port-Layout, aber separaten Instanzkontexten.</li>\n<li><strong>Schnittstellen & Port-Typen (pro Instanz):</strong></li>\n<li><strong>Sender-Receiver-Ports (Datenfluss):</strong></li>\n<li><code>SeatSwitch</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Einlesen des Taster-/Schalterzustands.</li>\n<li><code>PowerManagement</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Empfang von Lastabwurf- und Leistungsbegrenzungsvorgaben des Bordnetzmanagements.</li>\n<li><code>DialLED</code> (P-Port / Provider): Schwarzes Dreieck auswärts gerichtet; Ansteuerung der Statusanzeige/LEDs am Bedienelement.</li>\n<li><strong>Client-Server-Ports (Operationsbasiert):</strong></li>\n<li><code>Setting</code> (P-Port / Server): Kreis-/Ball-Symbol; Bereitstellung von Einstellungsdiensten oder Betriebsarten.</li>\n<li><code>HeatingElement</code> (R-Port / Client): Socket-/Halbkreis-Symbol einwärts gerichtet; Aufruf von Aktor-Services (z. B. Endstufen-/PWM-Regelung der Heizmatten).</li>\n<li><strong>Spezialisierte AUTOSAR-Service- & Parameter-Ports:</strong></li>\n<li><code>Calibration</code> (Parameter-Port): Weißes Dreieck einwärts gerichtet; typisiert über ein <code>ParameterInterface</code> zum Zugriff auf Kennlinien und Schwellwerte.</li>\n<li><code>nv</code> (NvData-Port): Weißes Quadrat mit schwarzem Dreiecksymbol am unteren Rand; Anbindung an das <code>NvDataInterface</code> zur persistenten Speicherung (z. B. Memory-Funktion/letzte Heizstufe via NvM).</li>\n<li><code>ecuMode</code> (Mode-Switch-Port): Dunkler Block mit weißem Dreieck am unteren Rand; Typisiert über <code>ModeSwitchInterface</code> zur Steuerung des Run-Status abhängig von BSW-Modi (z. B. <code>RUN</code>, <code>POST_RUN</code>, <code>SHUTDOWN</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Strukturdiagramm handelt, wird kein Zeitablauf dargestellt. Das Laufzeitverhalten leitet sich aus den RTE-Events ab:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Init-/Startup-Phase:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Moduswechsel an <code>ecuMode</code> erzeugt ein <code>ModeSwitchEvent</code>.</li>\n<li>Restore der letzten Betriebszustände über <code>nv</code> (asynchroner NvM-Read-Job bzw. Initial-RAM-Mirror-Lesezugriff).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zyklischer Regelkreis:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>TimingEvent</code> oder <code>DataReceivedEvent</code> an <code>SeatSwitch</code> aktiviert die Steuerungs-Runnable.</li>\n<li>Prüfung der zulässigen Heizleistung gegen empfangene Drosselungswerte aus <code>PowerManagement</code>.</li>\n<li>Abgleich mit Kennwerten über den <code>Calibration</code>-Port.</li>\n<li>Synchoner/asynchroner Operationsaufruf (<code>Rte_Call</code>) an <code>HeatingElement</code> zur Bestromung der Heizdrähte.</li>\n<li>Asynchrones Datensenden (<code>Rte_Write</code>) des aktuellen Zustands an <code>DialLED</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbruch-/Grenzbedingungen:</strong> Bei Lastabwurfanforderung via <code>PowerManagement</code> oder Erkennung von Unter-/Überspannung erfolgt die Abregelung oder Abschaltung des Heizelements.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architekturvorgaben:</strong></li>\n<li>Das Diagramm dokumentiert die normative Semantik von <code>SwComponentPrototype</code> innerhalb einer VFB-Architektur. Beide Prototypen greifen auf denselben <code>AtomicSoftwareComponentType</code> zu.</li>\n<li>Die Ports definieren formale Schnittstellenverträge (Sender-Receiver-, Client-Server-, Parameter-, NvData- und Mode-Switch-Interfaces).</li>\n<li><strong>Implementierung & RTE-Generierung:</strong></li>\n<li>Da es sich um Mehrfachinstanziierung handelt, muss der RTE-Generator für jede Instanz separate Datenstrukturen (RTE-Instanzdaten) und Instanzzeiger (<code>self</code>-Pointer in C-Schnittstellen wie <code>Rte_Instance</code>) anlegen.</li>\n<li>Jede Instanz erhält separate RTE-APIs mit instanzspezifischem Prefix oder Instanzhandle (z. B. <code>Rte_IRead_SHCFrontLeft_...</code> vs. <code>Rte_IRead_SHCFrontRight_...</code>).</li>\n<li>Nicht-flüchtige Daten (<code>nv</code>) müssen im RTE- und NvM-Mapping eindeutigen NVRAM-Blöcken je Instanz zugeordnet werden, um gegenseitiges Überschreiben zu verhindern.</li>\n</ul>"}, {"id": "FIG-b16d55fa285ca000", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB (Virtual Functional Bus) Komponentendiagramm / Software-Architekturdiagramm (UML-2-Komponentennotation mit AUTOSAR-spezifischen VFB-Portsymbolen).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Veranschaulichung der Mehrfachinstanziierung (<em>Multiple Instantiation</em>) eines einzelnen Software-Komponententyps (<code>AtomicSoftwareComponentType</code> bzw. <code>ApplicationSoftwareComponentType</code>: <code>SeatHeatingControl</code>) in zwei distinkte Komponenten-Prototypen (<code>SwComponentPrototype</code>: <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>).</li>\n<li><strong>Systemkontext:</strong> VFB-Ebene vor der Allokation auf konkrete Steuergeräte (ECUs). Zeigt die vollständige logische Entkopplung von identischer Implementierung und instanzspezifischer Schnittstellenbindung für symmetrische Fahrzeugfunktionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponententyp & Prototypen:</strong></li>\n<li><code>SeatHeatingControl</code> (<code>isOfType</code>): Basistyp, der das gemeinsame <code>SwcInternalBehavior</code> definiert.</li>\n<li><code>SHCFrontLeft</code>, <code>SHCFrontRight</code>: Konkrete Komponenten-Prototypen (<code>SwComponentPrototype</code>) mit identischem Port-Layout, aber separaten Instanzkontexten.</li>\n<li><strong>Schnittstellen & Port-Typen (pro Instanz):</strong></li>\n<li><strong>Sender-Receiver-Ports (Datenfluss):</strong></li>\n<li><code>SeatSwitch</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Einlesen des Taster-/Schalterzustands.</li>\n<li><code>PowerManagement</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Empfang von Lastabwurf- und Leistungsbegrenzungsvorgaben des Bordnetzmanagements.</li>\n<li><code>DialLED</code> (P-Port / Provider): Schwarzes Dreieck auswärts gerichtet; Ansteuerung der Statusanzeige/LEDs am Bedienelement.</li>\n<li><strong>Client-Server-Ports (Operationsbasiert):</strong></li>\n<li><code>Setting</code> (P-Port / Server): Kreis-/Ball-Symbol; Bereitstellung von Einstellungsdiensten oder Betriebsarten.</li>\n<li><code>HeatingElement</code> (R-Port / Client): Socket-/Halbkreis-Symbol einwärts gerichtet; Aufruf von Aktor-Services (z. B. Endstufen-/PWM-Regelung der Heizmatten).</li>\n<li><strong>Spezialisierte AUTOSAR-Service- & Parameter-Ports:</strong></li>\n<li><code>Calibration</code> (Parameter-Port): Weißes Dreieck einwärts gerichtet; typisiert über ein <code>ParameterInterface</code> zum Zugriff auf Kennlinien und Schwellwerte.</li>\n<li><code>nv</code> (NvData-Port): Weißes Quadrat mit schwarzem Dreiecksymbol am unteren Rand; Anbindung an das <code>NvDataInterface</code> zur persistenten Speicherung (z. B. Memory-Funktion/letzte Heizstufe via NvM).</li>\n<li><code>ecuMode</code> (Mode-Switch-Port): Schwarzes Quadrat mit drei weißen Punkten in Dreiecksanordnung am unteren Rand; typisiert über <code>ModeSwitchInterface</code> zur Steuerung des Run-Status abhängig von BSW-Modi (z. B. <code>RUN</code>, <code>POST_RUN</code>, <code>SHUTDOWN</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Strukturdiagramm handelt, wird kein Zeitablauf dargestellt. Das Laufzeitverhalten leitet sich aus den RTE-Events ab:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Init-/Startup-Phase:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Moduswechsel an <code>ecuMode</code> erzeugt ein <code>ModeSwitchEvent</code>.</li>\n<li>Restore der letzten Betriebszustände über <code>nv</code> (asynchroner NvM-Read-Job bzw. Initial-RAM-Mirror-Lesezugriff).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zyklischer Regelkreis:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>TimingEvent</code> oder <code>DataReceivedEvent</code> an <code>SeatSwitch</code> aktiviert die Steuerungs-Runnable.</li>\n<li>Prüfung der zulässigen Heizleistung gegen empfangene Drosselungswerte aus <code>PowerManagement</code>.</li>\n<li>Abgleich mit Kennwerten über den <code>Calibration</code>-Port.</li>\n<li>Synchoner/asynchroner Operationsaufruf (<code>Rte_Call</code>) an <code>HeatingElement</code> zur Bestromung der Heizdrähte.</li>\n<li>Asynchrones Datensenden (<code>Rte_Write</code>) des aktuellen Zustands an <code>DialLED</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbruch-/Grenzbedingungen:</strong> Bei Lastabwurfanforderung via <code>PowerManagement</code> oder Erkennung von Unter-/Überspannung erfolgt die Abregelung oder Abschaltung des Heizelements.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architekturvorgaben:</strong></li>\n<li>Das Diagramm dokumentiert die normative Semantik von <code>SwComponentPrototype</code> innerhalb einer VFB-Architektur. Beide Prototypen greifen auf denselben <code>AtomicSoftwareComponentType</code> zu.</li>\n<li>Die Ports definieren formale Schnittstellenverträge (Sender-Receiver-, Client-Server-, Parameter-, NvData- und Mode-Switch-Interfaces).</li>\n<li><strong>Implementierung & RTE-Generierung:</strong></li>\n<li>Da es sich um Mehrfachinstanziierung handelt, muss der RTE-Generator für jede Instanz separate Datenstrukturen (RTE-Instanzdaten) und Instanzzeiger (<code>self</code>-Pointer in C-Schnittstellen wie <code>Rte_Instance</code>) anlegen.</li>\n<li>Jede Instanz erhält separate RTE-APIs mit instanzspezifischem Prefix oder Instanzhandle (z. B. <code>Rte_IRead_SHCFrontLeft_...</code> vs. <code>Rte_IRead_SHCFrontRight_...</code>).</li>\n<li>Nicht-flüchtige Daten (<code>nv</code>) müssen im RTE- und NvM-Mapping eindeutigen NVRAM-Blöcken je Instanz zugeordnet werden, um gegenseitiges Überschreiben zu verhindern.</li>\n</ul>"}, {"id": "FIG-795f913af6c98fc4", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB (Virtual Functional Bus) Komponentendiagramm / Software-Architekturdiagramm (UML-2-Komponentennotation mit AUTOSAR-spezifischen VFB-Portsymbolen).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Veranschaulichung der Mehrfachinstanziierung (<em>Multiple Instantiation</em>) eines einzelnen Software-Komponententyps (<code>AtomicSoftwareComponentType</code> bzw. <code>ApplicationSoftwareComponentType</code>: <code>SeatHeatingControl</code>) in zwei distinkte Komponenten-Prototypen (<code>SwComponentPrototype</code>: <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>).</li>\n<li><strong>Systemkontext:</strong> VFB-Ebene vor der Allokation auf konkrete Steuergeräte (ECUs). Zeigt die vollständige logische Entkopplung von identischer Implementierung und instanzspezifischer Schnittstellenbindung für symmetrische Fahrzeugfunktionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponententyp & Prototypen:</strong></li>\n<li><code>SeatHeatingControl</code> (<code>isOfType</code>): Basistyp, der das gemeinsame <code>SwcInternalBehavior</code> definiert.</li>\n<li><code>SHCFrontLeft</code>, <code>SHCFrontRight</code>: Konkrete Komponenten-Prototypen (<code>SwComponentPrototype</code>) mit identischem Port-Layout, aber separaten Instanzkontexten.</li>\n<li><strong>Schnittstellen & Port-Typen (pro Instanz):</strong></li>\n<li><strong>Sender-Receiver-Ports (Datenfluss):</strong></li>\n<li><code>SeatSwitch</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Einlesen des Taster-/Schalterzustands.</li>\n<li><code>PowerManagement</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Empfang von Lastabwurf- und Leistungsbegrenzungsvorgaben des Bordnetzmanagements.</li>\n<li><code>DialLED</code> (P-Port / Provider): Schwarzes Dreieck auswärts gerichtet; Ansteuerung der Statusanzeige/LEDs am Bedienelement.</li>\n<li><strong>Client-Server-Ports (Operationsbasiert):</strong></li>\n<li><code>Setting</code> (P-Port / Server): Kreis-/Ball-Symbol; Bereitstellung von Einstellungsdiensten oder Betriebsarten.</li>\n<li><code>HeatingElement</code> (R-Port / Client): Socket-/Halbkreis-Symbol einwärts gerichtet; Aufruf von Aktor-Services (z. B. Endstufen-/PWM-Regelung der Heizmatten).</li>\n<li><strong>Spezialisierte AUTOSAR-Service- & Parameter-Ports:</strong></li>\n<li><code>Calibration</code> (Parameter-Port): Weißes Dreieck einwärts gerichtet; typisiert über ein <code>ParameterInterface</code> zum Zugriff auf Kennlinien und Schwellwerte.</li>\n<li><code>nv</code> (NvData-Port): Weißes Quadrat mit schwarzem Dreiecksymbol am unteren Rand; Anbindung an das <code>NvDataInterface</code> zur persistenten Speicherung (z. B. Memory-Funktion/letzte Heizstufe via NvM).</li>\n<li><code>ecuMode</code> (Mode-Switch-Port): Schwarzes Quadrat mit drei weißen Punkten in Dreiecksanordnung am unteren Rand; typisiert über <code>ModeSwitchInterface</code> zur Steuerung des Run-Status abhängig von BSW-Modi (z. B. <code>RUN</code>, <code>POST_RUN</code>, <code>SHUTDOWN</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Strukturdiagramm handelt, wird kein Zeitablauf dargestellt. Das Laufzeitverhalten leitet sich aus den RTE-Events ab:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Init-/Startup-Phase:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Moduswechsel an <code>ecuMode</code> erzeugt ein <code>ModeSwitchEvent</code>.</li>\n<li>Restore der letzten Betriebszustände über <code>nv</code> (asynchroner NvM-Read-Job bzw. Initial-RAM-Mirror-Lesezugriff).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zyklischer Regelkreis:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>TimingEvent</code> oder <code>DataReceivedEvent</code> an <code>SeatSwitch</code> aktiviert die Steuerungs-Runnable.</li>\n<li>Prüfung der zulässigen Heizleistung gegen empfangene Drosselungswerte aus <code>PowerManagement</code>.</li>\n<li>Abgleich mit Kennwerten über den <code>Calibration</code>-Port.</li>\n<li>Synchoner/asynchroner Operationsaufruf (<code>Rte_Call</code>) an <code>HeatingElement</code> zur Bestromung der Heizdrähte.</li>\n<li>Asynchrones Datensenden (<code>Rte_Write</code>) des aktuellen Zustands an <code>DialLED</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbruch-/Grenzbedingungen:</strong> Bei Lastabwurfanforderung via <code>PowerManagement</code> oder Erkennung von Unter-/Überspannung erfolgt die Abregelung oder Abschaltung des Heizelements.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architekturvorgaben:</strong></li>\n<li>Das Diagramm dokumentiert die normative Semantik von <code>SwComponentPrototype</code> innerhalb einer VFB-Architektur. Beide Prototypen greifen auf denselben <code>AtomicSoftwareComponentType</code> zu.</li>\n<li>Die Ports definieren formale Schnittstellenverträge (Sender-Receiver-, Client-Server-, Parameter-, NvData- und Mode-Switch-Interfaces).</li>\n<li><strong>Implementierung & RTE-Generierung:</strong></li>\n<li>Da es sich um Mehrfachinstanziierung handelt, muss der RTE-Generator für jede Instanz separate Datenstrukturen (RTE-Instanzdaten) und Instanzzeiger (<code>self</code>-Pointer in C-Schnittstellen wie <code>Rte_Instance</code>) anlegen.</li>\n<li>Jede Instanz erhält separate RTE-APIs mit instanzspezifischem Prefix oder Instanzhandle (z. B. <code>Rte_IRead_SHCFrontLeft_...</code> vs. <code>Rte_IRead_SHCFrontRight_...</code>).</li>\n<li>Nicht-flüchtige Daten (<code>nv</code>) müssen im RTE- und NvM-Mapping eindeutigen NVRAM-Blöcken je Instanz zugeordnet werden, um gegenseitiges Überschreiben zu verhindern.</li>\n</ul>"}, {"id": "FIG-af30d4c5c0889404", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB (Virtual Functional Bus) Komponentendiagramm / Software-Architekturdiagramm (UML-2-Komponentennotation mit AUTOSAR-spezifischen VFB-Portsymbolen).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Veranschaulichung der Mehrfachinstanziierung (<em>Multiple Instantiation</em>) eines einzelnen Software-Komponententyps (<code>AtomicSoftwareComponentType</code> bzw. <code>ApplicationSoftwareComponentType</code>: <code>SeatHeatingControl</code>) in zwei distinkte Komponenten-Prototypen (<code>SwComponentPrototype</code>: <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>).</li>\n<li><strong>Systemkontext:</strong> VFB-Ebene vor der Allokation auf konkrete Steuergeräte (ECUs). Zeigt die vollständige logische Entkopplung von identischer Implementierung und instanzspezifischer Schnittstellenbindung für symmetrische Fahrzeugfunktionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponententyp & Prototypen:</strong></li>\n<li><code>SeatHeatingControl</code> (<code>isOfType</code>): Basistyp, der das gemeinsame <code>SwcInternalBehavior</code> definiert.</li>\n<li><code>SHCFrontLeft</code>, <code>SHCFrontRight</code>: Konkrete Komponenten-Prototypen (<code>SwComponentPrototype</code>) mit identischem Port-Layout, aber separaten Instanzkontexten.</li>\n<li><strong>Schnittstellen & Port-Typen (pro Instanz):</strong></li>\n<li><strong>Sender-Receiver-Ports (Datenfluss):</strong></li>\n<li><code>SeatSwitch</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Einlesen des Taster-/Schalterzustands.</li>\n<li><code>PowerManagement</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Empfang von Lastabwurf- und Leistungsbegrenzungsvorgaben des Bordnetzmanagements.</li>\n<li><code>DialLED</code> (P-Port / Provider): Schwarzes Dreieck auswärts gerichtet; Ansteuerung der Statusanzeige/LEDs am Bedienelement.</li>\n<li><strong>Client-Server-Ports (Operationsbasiert):</strong></li>\n<li><code>Setting</code> (P-Port / Server): Kreis-/Ball-Symbol; Bereitstellung von Einstellungsdiensten oder Betriebsarten.</li>\n<li><code>HeatingElement</code> (R-Port / Client): Socket-/Halbkreis-Symbol einwärts gerichtet; Aufruf von Aktor-Services (z. B. Endstufen-/PWM-Regelung der Heizmatten).</li>\n<li><strong>Spezialisierte AUTOSAR-Service- & Parameter-Ports:</strong></li>\n<li><code>Calibration</code> (Parameter-Port): Weißes Dreieck einwärts gerichtet; typisiert über ein <code>ParameterInterface</code> zum Zugriff auf Kennlinien und Schwellwerte.</li>\n<li><code>nv</code> (NvData-Port): Weißes Quadrat mit schwarzem Dreiecksymbol am unteren Rand; Anbindung an das <code>NvDataInterface</code> zur persistenten Speicherung (z. B. Memory-Funktion/letzte Heizstufe via NvM).</li>\n<li><code>ecuMode</code> (Mode-Switch-Port): Schwarzes Quadrat mit drei weißen Punkten in Dreiecksanordnung am unteren Rand; typisiert über <code>ModeSwitchInterface</code> zur Steuerung des Run-Status abhängig von BSW-Modi (z. B. <code>RUN</code>, <code>POST_RUN</code>, <code>SHUTDOWN</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Strukturdiagramm handelt, wird kein Zeitablauf dargestellt. Das Laufzeitverhalten leitet sich aus den RTE-Events ab:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Init-/Startup-Phase:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Moduswechsel an <code>ecuMode</code> erzeugt ein <code>ModeSwitchEvent</code>.</li>\n<li>Restore der letzten Betriebszustände über <code>nv</code> (asynchroner NvM-Read-Job bzw. Initial-RAM-Mirror-Lesezugriff).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zyklischer Regelkreis:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>TimingEvent</code> oder <code>DataReceivedEvent</code> an <code>SeatSwitch</code> aktiviert die Steuerungs-Runnable.</li>\n<li>Prüfung der zulässigen Heizleistung gegen empfangene Drosselungswerte aus <code>PowerManagement</code>.</li>\n<li>Abgleich mit Kennwerten über den <code>Calibration</code>-Port.</li>\n<li>Synchoner/asynchroner Operationsaufruf (<code>Rte_Call</code>) an <code>HeatingElement</code> zur Bestromung der Heizdrähte.</li>\n<li>Asynchrones Datensenden (<code>Rte_Write</code>) des aktuellen Zustands an <code>DialLED</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbruch-/Grenzbedingungen:</strong> Bei Lastabwurfanforderung via <code>PowerManagement</code> oder Erkennung von Unter-/Überspannung erfolgt die Abregelung oder Abschaltung des Heizelements.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architekturvorgaben:</strong></li>\n<li>Das Diagramm dokumentiert die normative Semantik von <code>SwComponentPrototype</code> innerhalb einer VFB-Architektur. Beide Prototypen greifen auf denselben <code>AtomicSoftwareComponentType</code> zu.</li>\n<li>Die Ports definieren formale Schnittstellenverträge (Sender-Receiver-, Client-Server-, Parameter-, NvData- und Mode-Switch-Interfaces).</li>\n<li><strong>Implementierung & RTE-Generierung:</strong></li>\n<li>Da es sich um Mehrfachinstanziierung handelt, muss der RTE-Generator für jede Instanz separate Datenstrukturen (RTE-Instanzdaten) und Instanzzeiger (<code>self</code>-Pointer in C-Schnittstellen wie <code>Rte_Instance</code>) anlegen.</li>\n<li>Jede Instanz erhält separate RTE-APIs mit instanzspezifischem Prefix oder Instanzhandle (z. B. <code>Rte_IRead_SHCFrontLeft_...</code> vs. <code>Rte_IRead_SHCFrontRight_...</code>).</li>\n<li>Nicht-flüchtige Daten (<code>nv</code>) müssen im RTE- und NvM-Mapping eindeutigen NVRAM-Blöcken je Instanz zugeordnet werden, um gegenseitiges Überschreiben zu verhindern.</li>\n</ul>"}, {"id": "FIG-40696df42eec1e0a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB (Virtual Functional Bus) Komponentendiagramm / Software-Architekturdiagramm (UML-2-Komponentennotation mit AUTOSAR-spezifischen VFB-Portsymbolen).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Veranschaulichung der Mehrfachinstanziierung (<em>Multiple Instantiation</em>) eines einzelnen Software-Komponententyps (<code>AtomicSoftwareComponentType</code> bzw. <code>ApplicationSoftwareComponentType</code>: <code>SeatHeatingControl</code>) in zwei distinkte Komponenten-Prototypen (<code>SwComponentPrototype</code>: <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>).</li>\n<li><strong>Systemkontext:</strong> VFB-Ebene vor der Allokation auf konkrete Steuergeräte (ECUs). Zeigt die vollständige logische Entkopplung von identischer Implementierung und instanzspezifischer Schnittstellenbindung für symmetrische Fahrzeugfunktionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponententyp & Prototypen:</strong></li>\n<li><code>SeatHeatingControl</code> (<code>isOfType</code>): Basistyp, der das gemeinsame <code>SwcInternalBehavior</code> definiert.</li>\n<li><code>SHCFrontLeft</code>, <code>SHCFrontRight</code>: Konkrete Komponenten-Prototypen (<code>SwComponentPrototype</code>) mit identischem Port-Layout, aber separaten Instanzkontexten.</li>\n<li><strong>Schnittstellen & Port-Typen (pro Instanz):</strong></li>\n<li><strong>Sender-Receiver-Ports (Datenfluss):</strong></li>\n<li><code>SeatSwitch</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Einlesen des Taster-/Schalterzustands.</li>\n<li><code>PowerManagement</code> (R-Port / Receiver): Schwarzes Dreieck einwärts gerichtet; Empfang von Lastabwurf- und Leistungsbegrenzungsvorgaben des Bordnetzmanagements.</li>\n<li><code>DialLED</code> (P-Port / Provider): Schwarzes Dreieck auswärts gerichtet; Ansteuerung der Statusanzeige/LEDs am Bedienelement.</li>\n<li><strong>Client-Server-Ports (Operationsbasiert):</strong></li>\n<li><code>Setting</code> (P-Port / Server): Kreis-/Ball-Symbol; Bereitstellung von Einstellungsdiensten oder Betriebsarten.</li>\n<li><code>HeatingElement</code> (R-Port / Client): Socket-/Halbkreis-Symbol einwärts gerichtet; Aufruf von Aktor-Services (z. B. Endstufen-/PWM-Regelung der Heizmatten).</li>\n<li><strong>Spezialisierte AUTOSAR-Service- & Parameter-Ports:</strong></li>\n<li><code>Calibration</code> (Parameter-Port): Weißes Dreieck einwärts gerichtet; typisiert über ein <code>ParameterInterface</code> zum Zugriff auf Kennlinien und Schwellwerte.</li>\n<li><code>nv</code> (NvData-Port): Weißes Quadrat mit schwarzem Dreiecksymbol am unteren Rand; Anbindung an das <code>NvDataInterface</code> zur persistenten Speicherung (z. B. Memory-Funktion/letzte Heizstufe via NvM).</li>\n<li><code>ecuMode</code> (Mode-Switch-Port): Schwarzes Quadrat mit drei weißen Punkten in Dreiecksanordnung am unteren Rand; typisiert über <code>ModeSwitchInterface</code> zur Steuerung des Run-Status abhängig von BSW-Modi (z. B. <code>RUN</code>, <code>POST_RUN</code>, <code>SHUTDOWN</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Strukturdiagramm handelt, wird kein Zeitablauf dargestellt. Das Laufzeitverhalten leitet sich aus den RTE-Events ab:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Init-/Startup-Phase:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Moduswechsel an <code>ecuMode</code> erzeugt ein <code>ModeSwitchEvent</code>.</li>\n<li>Restore der letzten Betriebszustände über <code>nv</code> (asynchroner NvM-Read-Job bzw. Initial-RAM-Mirror-Lesezugriff).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zyklischer Regelkreis:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>TimingEvent</code> oder <code>DataReceivedEvent</code> an <code>SeatSwitch</code> aktiviert die Steuerungs-Runnable.</li>\n<li>Prüfung der zulässigen Heizleistung gegen empfangene Drosselungswerte aus <code>PowerManagement</code>.</li>\n<li>Abgleich mit Kennwerten über den <code>Calibration</code>-Port.</li>\n<li>Synchoner/asynchroner Operationsaufruf (<code>Rte_Call</code>) an <code>HeatingElement</code> zur Bestromung der Heizdrähte.</li>\n<li>Asynchrones Datensenden (<code>Rte_Write</code>) des aktuellen Zustands an <code>DialLED</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbruch-/Grenzbedingungen:</strong> Bei Lastabwurfanforderung via <code>PowerManagement</code> oder Erkennung von Unter-/Überspannung erfolgt die Abregelung oder Abschaltung des Heizelements.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architekturvorgaben:</strong></li>\n<li>Das Diagramm dokumentiert die normative Semantik von <code>SwComponentPrototype</code> innerhalb einer VFB-Architektur. Beide Prototypen greifen auf denselben <code>AtomicSoftwareComponentType</code> zu.</li>\n<li>Die Ports definieren formale Schnittstellenverträge (Sender-Receiver-, Client-Server-, Parameter-, NvData- und Mode-Switch-Interfaces).</li>\n<li><strong>Implementierung & RTE-Generierung:</strong></li>\n<li>Da es sich um Mehrfachinstanziierung handelt, muss der RTE-Generator für jede Instanz separate Datenstrukturen (RTE-Instanzdaten) und Instanzzeiger (<code>self</code>-Pointer in C-Schnittstellen wie <code>Rte_Instance</code>) anlegen.</li>\n<li>Jede Instanz erhält separate RTE-APIs mit instanzspezifischem Prefix oder Instanzhandle (z. B. <code>Rte_IRead_SHCFrontLeft_...</code> vs. <code>Rte_IRead_SHCFrontRight_...</code>).</li>\n<li>Nicht-flüchtige Daten (<code>nv</code>) müssen im RTE- und NvM-Mapping eindeutigen NVRAM-Blöcken je Instanz zugeordnet werden, um gegenseitiges Überschreiben zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-d4f40b95450712d1", "to": "FIG-be9c3b3fc79318cb", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Port <code>nv</code>: Das Portsymbol am unteren Rand beider Instanzen wurde von einem schwarzen Quadrat mit weißem Halbkreis zu einem weißen Quadrat mit schwarzem Dreieck und innenliegendem Punkt/Dreieck (Standard-Symbolik für NvData-Ports) korrigiert.</li>\n<li>Port <code>ecuMode</code>: Das Dreiecksymbol im schwarzen Port-Quadrat wurde grafisch invertiert bzw. überarbeitet (weißes Dreieck auf schwarzem Grund nun mit klarer Kontur).</li>\n<li>Typo-Korrektur: Das doppelte Label „Setting Setting“ aus der Vorab-Extraktion war ein OCR-Artefakt; grafisch wurde das Port-Icon von <code>nv</code> aktualisiert.</li>\n</ul>"}, {"from": "FIG-be9c3b3fc79318cb", "to": "FIG-b16d55fa285ca000", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Port <code>ecuMode</code>: Das Portsymbol am unteren Rand beider Instanzen wurde von einem schwarzen Quadrat mit zentriertem Dreieck zu einem schwarzen Quadrat mit drei weißen Punkten (Dreiecksanordnung, Mode-Switch-Port-Symbolik nach AUTOSAR 4) geändert.</li>\n</ul>"}, {"from": "FIG-b16d55fa285ca000", "to": "FIG-795f913af6c98fc4", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-795f913af6c98fc4", "to": "FIG-af30d4c5c0889404", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-af30d4c5c0889404", "to": "FIG-40696df42eec1e0a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
